#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//enum {  eTypeHsCircle=0,  eTypeSensorCircle=1,  eTypePumpCircle=2,};// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  //(по HS.PV м.б. 4 значения разных текста и цветов)  //если PV>4 или <0 то ничего не отображается  char szName[64];//используется как Txt0  char szTxt[4][64];  COLORREF colorTxt[4];  COLORREF colorBkg[4];  bool bWithoutEdge;  UINT uFormat;  bool bSomeStrings;  bool bHide0Show1;  int nTeg;  int nTypeTrans;  bool bBiggerSensor;  double valueForCompare;  int nShiftTextDown;  } Queue_ColorCircle;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int RectHeightC( const RECT &rect )    {      return rect.bottom - rect.top;    }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void WordC( HDC m_hDC, const char* text, RECT& rc, UINT uFormat )      {        if ( text && *text )        {//DT_VCENTER не совместим с DT_WORDBREAK поэтому самостоятельно вычисляем          RECT orig( rc );          RECT tRect( orig );          const int l = lstrlen(text);          ::DrawText( m_hDC, text, l, &tRect, uFormat|DT_CALCRECT );          orig.top += ( RectHeightC(orig) - RectHeightC(tRect) ) / 2;          ::DrawText( m_hDC, text, l, &orig, uFormat );        }      }void DrawTextMyC( HDC hDC, const char* text1, const char* text2, RECT& rc, UINT uFormat, bool bSomeStrings, int nShiftTextDown ){          RECT rcShift=rc;          rcShift.top+=nShiftTextDown;          if (bSomeStrings)              WordC( hDC, text1, rcShift, uFormat );          else			        ::DrawText( hDC, text1, lstrlen(text1), &rcShift, uFormat );}void DrawBadCircle( HDC hDC, const char* text1,const char* text2, RECT& rc, UINT uFormat, bool bSomeStrings, int nShiftTextDown){           if ( ::GetMnemoStyle() & MNEMO_EDIT )          {                CMyBrush brush( hDC, 0x80ff,true );                brush.Ellipse( rc );        	      CMyPen pen( hDC, 0x80ff );                pen.Ellipse( rc );                COLORREF old = ::SetTextColor( hDC, 0x0);                DrawTextMyC( hDC, text1, text2, rc, uFormat, bSomeStrings, nShiftTextDown);			          ::SetTextColor( hDC, old );          }}void DrawFillCircle( HDC hDC, const char* text1,const char* text2, RECT& rc, UINT uFormat, bool bSomeStrings, COLORREF& clrBack, COLORREF& clrText, bool bWithoutEdge, int nShiftTextDown){	    CMyBrush brush( hDC, clrBack, true );	    brush.Ellipse( rc );	    COLORREF clrEdge=0;	    if (bWithoutEdge)		    clrEdge=clrBack;	    CMyPen pen( hDC, clrEdge );	    pen.Ellipse( rc );	    COLORREF old = ::SetTextColor( hDC, clrText );      DrawTextMyC( hDC, text1,text2, rc, uFormat, bSomeStrings, nShiftTextDown);	    ::SetTextColor( hDC, old );}// Функция отображенияint PaintColorCircle(DefinePaint)  {  QueueP(Queue_ColorCircle);  //  RECT rc = p->mRect;  int nNumber=-1;  const int dBadValue=-1021;    switch (p->nTypeTrans)  {    case eTypeHsCircle:      {        CShHS* sh = (CShHS*)PipeSh;	      if ( IsTypeOk )	      {          if (p->bHide0Show1)          {              if ( sh->mOn )                nNumber = 0;          }          else          {              if ( sh->mOn )                nNumber = 1;              else                nNumber = 0;          }	      }      }      break;    case eTypePumpCircle:      {        CShPump* sh = (CShPump*)PipeSh;	      if ( IsTypeOk )	      {          if (p->bHide0Show1)          {              if (sh->Eq_State( CPumpData::Work ))                nNumber = 0;          }          else          {              if (sh->Eq_State( CPumpData::Work ))                nNumber = 1;              else                nNumber = 0;          }	      }      }      break;    case eTypeSensorCircle:      {        CShSensor* sh = (CShSensor*)PipeSh;	      if ( IsTypeOk )	      {          if (p->bBiggerSensor)          {            if (sh->ShowValue>p->valueForCompare)              nNumber=1;            else              nNumber=0;          }          else          {             if (sh->ShowValue<p->valueForCompare)                nNumber=1;             else              nNumber=0;          }          if (p->bHide0Show1)          {            if (nNumber==1)              nNumber=0;            else              nNumber=-1;          }	      }      }      break;  }  if (nNumber==-1)      DrawBadCircle(hDC, p->szTxt[0],p->szTxt[1], rc, p->uFormat, p->bSomeStrings,p->nShiftTextDown);  else       DrawFillCircle( hDC, p->szTxt[nNumber],p->szTxt[1], rc, p->uFormat, p->bSomeStrings, p->colorBkg[nNumber], p->colorTxt[nNumber], p->bWithoutEdge,p->nShiftTextDown);  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddColorCircle(DefineTegs)  {  //  AddQueueEx(Queue_ColorCircle);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintColorCircle;  //  int nMultik = Multiline( p->szName, teg[0].value, sizeof(p->szName) );  p->uFormat = (nMultik) ?DT_CENTER|DT_WORDBREAK : DT_SINGLELINE|DT_VCENTER|DT_CENTER;  //  p->colorBkg[0]=0;  p->bWithoutEdge=false;  p->bSomeStrings=false;  p->bHide0Show1=false;  p->nNumber=-1;  p->nTeg=-1;  p->nTypeTrans=eTypeHsCircle;  char szHsName[64]="";  char szSensorName[64]="";  char szPumpName[64]="";  p->bBiggerSensor=false;  p->nShiftTextDown=0;  //  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },    { 'A', "cTxt0" , &p->colorTxt[0] },	{ 'A', "cTxt1" , &p->colorTxt[1] },	{ 'A', "cTxt2" , &p->colorTxt[2] },	{ 'A', "cTxt3" , &p->colorTxt[3] },	{ 'A', "cBkg0" , &p->colorBkg[0] },	{ 'A', "cBkg1" , &p->colorBkg[1] },	{ 'A', "cBkg2" , &p->colorBkg[2] },	{ 'A', "cBkg3" , &p->colorBkg[3] },	{ 'S', "txt1"  , p->szTxt[1], 63 },	{ 'S', "txt2"  , p->szTxt[2], 63 },	{ 'S', "txt3"  , p->szTxt[3], 63 },	{ 'B', "withoutEdge", &p->bWithoutEdge},  { 'B', "hide0show1", &p->bHide0Show1},	  { 'S', "hsName", szHsName, 63 },    { 'S', "sensorName", szSensorName, 63 },    { 'S', "pumpName", szPumpName, 63 },    { 'B', "bigger", &p->bBiggerSensor},    { 'D', "valueCompare" ,  &p->valueForCompare },    { 'I', "shiftTextDown" ,  &p->nShiftTextDown },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsName)	  p->nNumber=def.AddKind( id_HS    , szHsName );  else      if (*szSensorName)      {	        p->nNumber=def.AddKind( id_Sensor   , szSensorName );          p->nTypeTrans=eTypeSensorCircle;      }      else          if (*szPumpName)          {	            p->nNumber=def.AddKind( id_Pump   , szPumpName );              p->nTypeTrans=eTypePumpCircle;          }  if ((*(p->szTxt[1]))&&(nMultik))  {    Multiline( p->szTxt[1], p->szTxt[1], sizeof(p->szTxt[1]) );    p->bSomeStrings=true;  }  lstrcpy(p->szTxt[0],p->szName);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~